gdM(){return"\u042f\u043c\u0430\u0440 \u0447 \u0431\u0438\u0447\u0438\u0433 \u0431\u0430\u0440\u0438\u043c\u0442 \u043e\u043b\u0434\u0441\u043e\u043d\u0433\u04af\u0439"},
gcO(a){return"\u0425\u0430\u0439\u0445"},
gek(){return"\u04e9\u043c\u043d\u04e9"},
gev(){return"\u0425\u043e\u043b\u0431\u043e\u0445"},
gdt(){return"\u0425\u043e\u043b\u0431\u043e\u0436 \u0431\u0430\u0439\u043d\u0430"},
