gdf(){return"\u0420\u043e\u0437\u0448\u0438\u0440\u044e\u0439\u0442\u0435 \u0441\u0432\u043e\u044e \u0431\u0456\u0437\u043d\u0435\u0441-\u043c\u043e\u0434\u0435\u043b\u044c"},
gd3(){return"\u0417\u0430\u043b\u0443\u0447\u0430\u0439\u0442\u0435 \u0430\u0443\u0434\u0438\u0442\u043e\u0440\u0456\u044e \u043a\u043e\u0440\u043e\u0442\u043a\u0438\u043c\u0438 \u0432\u0456\u0434\u0435\u043e. \u041f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0456\u0442\u044c \u0441\u0432\u0456\u0439 \u0430\u043a\u0430\u0443\u043d\u0442 \u0456 \u0432\u0441\u0442\u0430\u043d\u043e\u0432\u0456\u0442\u044c \u0449\u043e\u043c\u0456\u0441\u044f\u0447\u043d\u0443 \u043f\u0456\u0434\u043f\u0438\u0441\u043a\u0443 \u0432\u0456\u0434 5 \u0434\u043e 100 \u0434\u043e\u043b\u0430\u0440\u0456\u0432 \u0434\u043b\u044f \u043f\u0443\u0431\u043b\u0456\u0447\u043d\u0438\u0445 \u0443\u0440\u043e\u043a\u0456\u0432, \u0435\u043a\u0441\u043a\u043b\u044e\u0437\u0438\u0432\u043d\u043e\u0433\u043e \u043a\u043e\u043d\u0442\u0435\u043d\u0442\u0443 \u0430\u0431\u043e \u0437\u0430\u043f\u0438\u0441\u0430\u043d\u0438\u0445 \u0434\u0437\u0432\u0456\u043d\u043a\u0456\u0432."},
gd5(){return"\u041d\u0430\u0432\u0447\u0430\u0439\u0442\u0435 \u0447\u0435\u0440\u0435\u0437 \u0437\u0430\u043f\u0438\u0441\u0430\u043d\u0456 \u0434\u0437\u0432\u0456\u043d\u043a\u0438. \u041f\u0440\u043e\u043f\u043e\u043d\u0443\u0439\u0442\u0435 \u0433\u0440\u0443\u043f\u043e\u0432\u0456 \u0430\u0431\u043e \u0456\u043d\u0434\u0438\u0432\u0456\u0434\u0443\u0430\u043b\u044c\u043d\u0456 \u0441\u0435\u0441\u0456\u0457 \u0442\u0430 \u0432\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u044e\u0439\u0442\u0435 \u0446\u0456\u043d\u0443 \u0432\u0456\u0434 5 \u0434\u043e 100 \u0434\u043e\u043b\u0430\u0440\u0456\u0432 \u0437\u0430 \u0434\u0437\u0432\u0456\u043d\u043e\u043a."},
gd6(){return"\u041c\u043e\u043d\u0435\u0442\u0438\u0437\u0443\u0439\u0442\u0435 \u0441\u0432\u043e\u0457 \u043a\u0443\u0440\u0441\u0438 \u0437 \u0446\u0456\u043d\u0430\u043c\u0438 \u0432\u0456\u0434 20 \u0434\u043e 500 \u0434\u043e\u043b\u0430\u0440\u0456\u0432. \u0414\u0456\u043b\u0456\u0442\u044c\u0441\u044f \u0441\u0432\u043e\u0454\u044e \u043f\u0440\u0438\u0441\u0442\u0440\u0430\u0441\u0442\u044e \u0447\u0435\u0440\u0435\u0437 \u0443\u0440\u043e\u043a\u0438, \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u0456 \u0442\u0430 \u043e\u0446\u0456\u043d\u044e\u0432\u0430\u043d\u043d\u044f, \u0442\u0430 \u043d\u0430\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0441\u0435\u0440\u0442\u0438\u0444\u0456\u043a\u0430\u0442 \u043f\u0456\u0441\u043b\u044f \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u043d\u044f."},
gd7(){return"\u0421\u0442\u0432\u043e\u0440\u044e\u0439\u0442\u0435 \u0435\u0444\u0435\u043a\u0442\u0438\u0432\u043d\u0456 \u0443\u0440\u043e\u043a\u0438 \u0437 \u0446\u0456\u043a\u0430\u0432\u0438\u043c\u0438 \u0432\u0441\u0442\u0443\u043f\u0430\u043c\u0438, \u043f\u043e\u0434\u043a\u0430\u0441\u0442\u0430\u043c\u0438, \u043c\u0443\u043b\u044c\u0442\u0438\u043c\u0435\u0434\u0456\u0439\u043d\u0438\u043c\u0438 \u0456\u0441\u0442\u043e\u0440\u0456\u044f\u043c\u0438 \u0447\u0438 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u043c\u0438. \u0414\u043e\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0437\u0430\u043f\u0438\u0442\u0430\u043d\u043d\u044f \u0437 \u0430\u0443\u0434\u0456\u043e, \u0432\u0456\u0434\u0435\u043e, \u0434\u0456\u0430\u0433\u0440\u0430\u043c\u0430\u043c\u0438 \u0442\u0430 \u043c\u0430\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u043d\u0438\u043c\u0438 \u0440\u0456\u0432\u043d\u044f\u043d\u043d\u044f\u043c\u0438. \u041e\u0442\u0440\u0438\u043c\u0443\u0439\u0442\u0435 \u0447\u0430\u0439\u043e\u0432\u0456 \u0432\u0456\u0434 1 \u0434\u043e 50 \u0434\u043e\u043b\u0430\u0440\u0456\u0432."},
gd8(){return"\u0421\u043f\u0456\u043b\u043a\u0443\u0439\u0442\u0435\u0441\u044f \u0437 \u0440\u0456\u0437\u043d\u043e\u043c\u0430\u043d\u0456\u0442\u043d\u043e\u044e \u0441\u043f\u0456\u043b\u044c\u043d\u043e\u0442\u043e\u044e, \u0437\u043d\u0430\u0439\u043e\u043c\u0442\u0435\u0441\u044c \u0437 \u043d\u043e\u0432\u0438\u043c\u0438 \u043b\u044e\u0434\u044c\u043c\u0438, \u043f\u0440\u0430\u043a\u0442\u0438\u043a\u0443\u0439\u0442\u0435 \u043c\u043e\u0432\u0438, \u043f\u0440\u043e\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u043a\u0443\u0440\u0441\u0438 \u0430\u0431\u043e \u043f\u0440\u043e\u0441\u0442\u043e \u0441\u043f\u0456\u043b\u043a\u0443\u0439\u0442\u0435\u0441\u044c \u0456 \u0434\u043e\u043c\u043e\u0432\u043b\u044f\u0439\u0442\u0435\u0441\u044c \u043f\u0440\u043e \u0437\u0430\u043f\u0438\u0441\u0430\u043d\u0456 \u0434\u0437\u0432\u0456\u043d\u043a\u0438 \u0434\u043b\u044f \u043d\u0430\u0432\u0447\u0430\u043d\u043d\u044f."},
gd9(){return"\u041f\u0440\u0430\u043a\u0442\u0438\u043a\u0443\u0439\u0442\u0435 \u043c\u043e\u0432\u0438 \u0437\u0430 \u0434\u043e\u043f\u043e\u043c\u043e\u0433\u043e\u044e \u0448\u0442\u0443\u0447\u043d\u043e\u0433\u043e \u0456\u043d\u0442\u0435\u043b\u0435\u043a\u0442\u0443 \u0434\u043b\u044f \u043f\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u043d\u044f \u0440\u043e\u0437\u0443\u043c\u0456\u043d\u043d\u044f. \u0414\u043e\u0441\u0442\u0443\u043f\u043d\u043e \u0448\u0456\u0441\u0442\u044c\u043c\u0430 \u043c\u043e\u0432\u0430\u043c\u0438."},
gda(){return"\u0420\u043e\u0437\u0448\u0438\u0440\u044e\u0439\u0442\u0435 \u0430\u0443\u0434\u0438\u0442\u043e\u0440\u0456\u044e, \u0434\u0456\u043b\u044f\u0447\u0438\u0441\u044c \u0437\u0430\u0445\u043e\u043f\u043b\u0438\u0432\u0438\u043c\u0438 \u0456\u0441\u0442\u043e\u0440\u0456\u044f\u043c\u0438, \u0434\u0435\u043c\u043e\u043d\u0441\u0442\u0440\u0443\u044e\u0447\u0438 \u0441\u0432\u0456\u0439 \u043f\u0440\u043e\u0433\u0440\u0435\u0441 \u0456 \u0434\u043e\u0441\u044f\u0433\u043d\u0435\u043d\u043d\u044f, \u0430 \u0442\u0430\u043a\u043e\u0436 \u0432\u0456\u0434\u043a\u0440\u0438\u0432\u0430\u044e\u0447\u0438 \u043d\u043e\u0432\u0456 \u0437\u043d\u0430\u0439\u043e\u043c\u0441\u0442\u0432\u0430."},
gdc(){return"\u0420\u043e\u0437\u0432\u0438\u0432\u0430\u0439\u0442\u0435 \u043a\u0456\u043b\u044c\u043a\u0430 \u0434\u0436\u0435\u0440\u0435\u043b \u0434\u043e\u0445\u043e\u0434\u0443, \u0437\u0430\u0439\u043c\u0430\u044e\u0447\u0438\u0441\u044c \u0446\u0438\u043c \u043f\u0440\u043e\u0444\u0435\u0441\u0456\u0439\u043d\u043e. \u0426\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 \u043f\u0456\u0434\u0440\u043e\u0431\u0456\u0442\u043e\u043a \u0430\u0431\u043e \u043f\u043e\u0432\u043d\u043e\u0446\u0456\u043d\u043d\u0430 \u043a\u0430\u0440\u2019\u0454\u0440\u0430 \u0437 \u0437\u043d\u0430\u0447\u043d\u0438\u043c \u043f\u043e\u0442\u0435\u043d\u0446\u0456\u0430\u043b\u043e\u043c \u0434\u043e\u0445\u043e\u0434\u0443."},
gdd(){return"\u0423\u043d\u0438\u043a\u0430\u0439\u0442\u0435 \u043e\u043f\u043b\u0430\u0442\u0438 \u0434\u043e\u0440\u043e\u0433\u0438\u0445 LMS-\u0441\u0438\u0441\u0442\u0435\u043c. \u0422\u0443\u0442 \u0432\u0438 \u043c\u043e\u0436\u0435\u0442\u0435 \u0441\u0442\u0432\u043e\u0440\u044e\u0432\u0430\u0442\u0438 \u044f\u043a\u0456\u0441\u043d\u0456 \u043a\u0443\u0440\u0441\u0438 \u0431\u0435\u0437 \u0448\u043a\u043e\u0434\u0438 \u0434\u043b\u044f \u043a\u043e\u043c\u0444\u043e\u0440\u0442\u0443 \u0447\u0438 \u044f\u043a\u043e\u0441\u0442\u0456 \u0434\u043b\u044f \u0441\u0442\u0443\u0434\u0435\u043d\u0442\u0456\u0432."},
